#pragma once
static void testStemJobs(const juce::File& root){
 auto dir=root.getChildFile("stem-jobs");dir.createDirectory();Session s(dir);s.importAudio(root.getChildFile("source.wav"),0,0);s.importAudio(root.getChildFile("source.wav"),1,0);s.setMix(0,-6.0205999f,0,false,false);int checks=0;
 auto wait=[&](StemJob& job){auto deadline=juce::Time::getMillisecondCounterHiRes()+30000;juce::String result;while(!job.poll(result)){require(juce::Time::getMillisecondCounterHiRes()<deadline,"Stem job timeout");juce::Thread::sleep(10);}return result;};
 StemJob good;auto final=dir.getChildFile("delivery");auto current=s.projectFile;good.start(s,final,{0,1},0,48000);s.setMix(0,0,0,true,false);wait(good);require(s.projectFile==current,"Stem snapshot changed current project");auto first=readWave(final.getChildFile("track-0.wav"));auto second=readWave(final.getChildFile("track-1.wav"));require(std::abs(first.getSample(0,12000)-0.0005f)<1e-7f&&std::abs(second.getSample(0,12000)-0.001f)<1e-7f,"Batch snapshot differs");++checks;
 s.setMix(0,0,0,false,false);StemJob cancelled;auto absent=dir.getChildFile("cancelled");cancelled.start(s,absent,{0,1},0,48000*60);cancelled.cancel();require(wait(cancelled)=="cancelled"&&!absent.exists(),"Cancelled stem job published");++checks;
 StemJob failed;auto noFinal=dir.getChildFile("failed");failed.start(s,noFinal,{0,99},0,48000);bool rejected=false;try{wait(failed);}catch(const std::exception&){rejected=true;}auto manifest=juce::JSON::parse(failed.folder.getChildFile("manifest.json"));require(rejected&&!noFinal.exists()&&manifest["status"].toString()=="failed"&&manifest["results"].isArray()&&manifest["results"].getArray()->size()==2,"Partial failure lacks per-stem results");require(failed.folder.getChildFile("outputs/track-0.wav").existsAsFile(),"Failed batch discarded diagnostic media");++checks;
 StemJob collision;auto occupied=dir.getChildFile("collision");collision.start(s,occupied,{0},0,48000);occupied.createDirectory();occupied.getChildFile("keep.txt").replaceWithText("keep");rejected=false;try{wait(collision);}catch(const std::exception&){rejected=true;}require(rejected&&occupied.getChildFile("keep.txt").loadFileAsString()=="keep"&&!occupied.getChildFile("track-0.wav").exists(),"Collision overwritten");++checks;
 StemJob duplicate;rejected=false;try{duplicate.start(s,dir.getChildFile("duplicate"),{0,0},0,48000);}catch(const std::exception&){rejected=true;}require(rejected&&!duplicate.active,"Duplicate stem accepted");++checks;

 auto published=juce::JSON::parse(final.getChildFile("manifest.json"));require(published["status"].toString()=="complete","Delivery manifest not complete");for(auto row:*published["results"].getArray())require(juce::SHA256(final.getChildFile(row["file"].toString())).toHexString()==row["sha256"].toString(),"Delivery stem hash differs");++checks;
 juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/editor/StudioTestGain_artefacts/Release/VST3/Studio Test Gain.vst3").getFullPathName());require(types.size()==1,"Batch fixture scan failed");s.engine.getPluginManager().initialise();s.engine.getPluginManager().knownPluginList.addType(*types[0]);auto plugin=s.edit->getPluginCache().createNewPlugin(te::ExternalPlugin::xmlTypeName,*types[0]);auto* external=dynamic_cast<te::ExternalPlugin*>(plugin.get());require(external!=nullptr,"Batch plugin failed");s.trackAt(0).pluginList.insertPlugin(plugin,0,nullptr);external->initialiseFully();require(external->getAudioPluginInstance()!=nullptr,"Batch plugin unavailable");external->getAudioPluginInstance()->getParameters()[0]->setValueNotifyingHost(0.25f);external->flushPluginStateToValueTree();
 StemJob effects;auto effectTarget=dir.getChildFile("with-plugin");effects.start(s,effectTarget,{0},0,48000);wait(effects);auto processed=readWave(effectTarget.getChildFile("track-0.wav"));require(std::abs(processed.getSample(0,12000)-0.00025f)<1e-7f,"Worker plugin state differs");++checks;
 auto* report=new juce::DynamicObject;juce::var value(report);report->setProperty("checks",checks);report->setProperty("snapshot_isolated",true);report->setProperty("cancel_no_final",true);report->setProperty("partial_failure_no_final",true);report->setProperty("collision_preserved",true);report->setProperty("device_opened",false);dir.getChildFile("stem-jobs-result.json").replaceWithText(juce::JSON::toString(value));
}
